<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Ubuntu Web Desktop</title>
<style>
  :root{
    --accent:#e95420;
    --accent-soft:rgba(233,84,32,.28);
    --panel:#2b2b31;
    --panel-dark:#232328;
    --panel-darker:#1b1b1f;
    --text:#f2f2f4;
    --muted:#9a9aa2;
    --border:#141417;
  }
  *{box-sizing:border-box;margin:0;padding:0}
  html,body{height:100%}
  body{
    font-family:"Ubuntu","Segoe UI",system-ui,-apple-system,sans-serif;
    overflow:hidden;background:#000;color:var(--text);
    -webkit-user-select:none;user-select:none;
  }

  /* ---------- Desktop ---------- */
  #desktop{
    position:fixed;inset:0;overflow:hidden;
    background:
      radial-gradient(1200px 700px at 78% 18%, rgba(233,84,32,.34), transparent 60%),
      radial-gradient(900px 600px at 15% 85%, rgba(119,41,83,.55), transparent 65%),
      radial-gradient(500px 500px at 55% 60%, rgba(233,84,32,.12), transparent 70%),
      linear-gradient(135deg,#2c001e 0%,#3d0f33 40%,#1a0b2e 100%);
  }
  #desktop::after{
    content:"";position:absolute;inset:0;pointer-events:none;
    background:
      repeating-linear-gradient(0deg, rgba(255,255,255,.015) 0 1px, transparent 1px 3px);
  }

  /* ---------- Taskbar / top bar ---------- */
  #taskbar{
    position:absolute;top:0;left:0;right:0;height:34px;z-index:100000;
    display:flex;align-items:center;gap:8px;padding:0 12px;
    background:rgba(14,14,18,.93);
    border-bottom:1px solid #000;
    box-shadow:0 1px 8px rgba(0,0,0,.5);
    font-size:12.5px;
  }
  .tb-brand{font-weight:700;letter-spacing:.3px;color:#ffb48f;margin-right:6px;font-size:13px}
  .tb-btn{
    display:flex;align-items:center;gap:7px;
    padding:4px 12px;border-radius:6px;border:1px solid transparent;
    background:transparent;color:var(--text);font-size:12.5px;cursor:pointer;
  }
  .tb-btn:hover{background:rgba(255,255,255,.08);border-color:rgba(255,255,255,.12)}
  .tb-btn:active{background:rgba(255,255,255,.14)}
  .tb-btn::before{font-size:14px;line-height:1}
  #open-files::before{content:"📁"}
  #open-notepad::before{content:"📝"}
  #clock{margin-left:auto;color:#d8d8de;font-variant-numeric:tabular-nums;white-space:nowrap}

  /* ---------- Windows ---------- */
  .window{
    position:absolute;display:none;flex-direction:column;
    min-width:360px;min-height:240px;
    width:700px;height:460px;
    background:var(--panel);
    border:1px solid #000;border-radius:10px;
    box-shadow:0 22px 60px rgba(0,0,0,.6), 0 2px 8px rgba(0,0,0,.4);
    overflow:hidden;
  }
  .win-titlebar{
    flex:none;display:flex;align-items:center;gap:10px;
    height:38px;padding:0 8px 0 14px;
    background:linear-gradient(#3d3d45,#2c2c33);
    border-bottom:1px solid var(--border);
    cursor:grab;
  }
  .win-titlebar:active{cursor:grabbing}
  .win-title{flex:1;font-size:13px;font-weight:600;color:#ececf0;pointer-events:none}
  .win-close{
    width:22px;height:22px;border-radius:50%;flex:none;
    border:none;background:#45454e;color:#cfcfd6;
    font-size:14px;line-height:1;cursor:pointer;
    display:flex;align-items:center;justify-content:center;
  }
  .win-close:hover{background:var(--accent);color:#fff}

  /* ---------- Files app ---------- */
  #files-window{left:110px;top:80px}
  .files-body{flex:1;display:flex;flex-direction:column;min-height:0}
  .files-toolbar{
    flex:none;display:flex;align-items:center;gap:10px;
    padding:8px 10px;background:var(--panel-dark);
    border-bottom:1px solid var(--border);
  }
  #files-up{
    padding:5px 14px;border-radius:6px;font-size:12.5px;
    border:1px solid #47474f;background:#36363e;color:var(--text);cursor:pointer;
  }
  #files-up:hover:not(:disabled){background:#43434d}
  #files-up:disabled{opacity:.4;cursor:default}
  #files-path{
    flex:1;padding:5px 12px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;
    background:var(--panel-darker);border:1px solid #3a3a42;border-radius:6px;
    font-family:"Ubuntu Mono","DejaVu Sans Mono",monospace;font-size:13px;color:#ffd3bd;
  }
  #files-list{
    flex:1;overflow-y:auto;padding:12px;min-height:0;
    display:grid;grid-template-columns:repeat(auto-fill,minmax(96px,1fr));
    gap:6px;align-content:start;
    background:#26262c;
  }
  .fs-item{
    display:flex;flex-direction:column;align-items:center;gap:7px;
    padding:12px 4px 10px;border-radius:8px;
    font-size:12.5px;text-align:center;word-break:break-word;line-height:1.25;
    border:1px solid transparent;cursor:default;
  }
  .fs-item::before{font-size:34px;line-height:1;display:block}
  .fs-item[data-type="dir"]::before{content:"📁"}
  .fs-item[data-type="file"]::before{content:"📄"}
  .fs-item:hover{background:rgba(255,255,255,.06)}
  .fs-item.sel{background:var(--accent-soft);border-color:var(--accent)}
  #files-status{
    flex:none;padding:5px 12px;font-size:11.5px;color:var(--muted);
    background:var(--panel-dark);border-top:1px solid var(--border);
  }

  /* ---------- Notepad app ---------- */
  #notepad-window{left:230px;top:120px;width:640px;height:440px}
  .tabstrip{
    flex:none;display:flex;align-items:stretch;min-height:36px;
    background:var(--panel-dark);border-bottom:1px solid var(--border);
  }
  #tabs{flex:1;display:flex;overflow-x:auto;scrollbar-width:thin;min-width:0}
  .tab{
    display:flex;align-items:center;gap:8px;flex:none;
    padding:0 8px 0 14px;max-width:180px;
    font-size:12.5px;color:#c9c9d1;cursor:pointer;white-space:nowrap;
    background:#28282e;border-right:1px solid var(--border);
  }
  .tab:hover{background:#303038}
  .tab.active{background:var(--panel);color:#fff;box-shadow:inset 0 2px 0 var(--accent)}
  .tab-name{overflow:hidden;text-overflow:ellipsis}
  .tab-x{
    flex:none;width:17px;height:17px;border-radius:50%;border:none;
    background:transparent;color:#a9a9b2;font-size:12px;line-height:1;cursor:pointer;
    display:flex;align-items:center;justify-content:center;
  }
  .tab-x:hover{background:var(--accent);color:#fff}
  #new-tab{
    flex:none;width:38px;border:none;background:transparent;
    color:#d5d5dc;font-size:19px;cursor:pointer;
  }
  #new-tab:hover{background:rgba(255,255,255,.08);color:#fff}
  .notepad-body{flex:1;display:flex;min-height:0}
  #editor{
    flex:1;resize:none;border:none;outline:none;
    background:#1e1e24;color:#ececf0;padding:14px;
    font-family:"Ubuntu Mono","DejaVu Sans Mono",monospace;font-size:13.5px;line-height:1.55;
    -webkit-user-select:text;user-select:text;
  }

  ::-webkit-scrollbar{width:10px;height:10px}
  ::-webkit-scrollbar-thumb{background:#4a4a52;border-radius:5px}
  ::-webkit-scrollbar-track{background:transparent}
</style>
</head>
<body>

<div id="desktop">

  <div id="taskbar">
    <span class="tb-brand">◆ Ubuntu</span>
    <button class="tb-btn" id="open-files">Files</button>
    <button class="tb-btn" id="open-notepad">Notepad</button>
    <span id="clock"></span>
  </div>

  <!-- Files window -->
  <section class="window" id="files-window" aria-label="Files">
    <header class="win-titlebar">
      <span class="win-title">Files</span>
      <button class="win-close" aria-label="Close">×</button>
    </header>
    <div class="files-body">
      <div class="files-toolbar">
        <button id="files-up">↑ Up</button>
        <span id="files-path">/</span>
      </div>
      <div id="files-list"></div>
      <div id="files-status"></div>
    </div>
  </section>

  <!-- Notepad window -->
  <section class="window" id="notepad-window" aria-label="Notepad">
    <header class="win-titlebar">
      <span class="win-title">Notepad</span>
      <button class="win-close" aria-label="Close">×</button>
    </header>
    <div class="tabstrip">
      <div id="tabs"></div>
      <button id="new-tab" title="New tab">+</button>
    </div>
    <div class="notepad-body">
      <textarea id="editor" spellcheck="false" placeholder="Type here…"></textarea>
    </div>
  </section>

</div>

<script>
(function(){
  "use strict";

  /* ================= Fake filesystem ================= */
  const F = (content) => ({ type:"file", content: content || "" });
  const D = (children) => ({ type:"dir", children: children || {} });

  const FS = D({
    "bin":  D({ "bash":F(), "cat":F(), "echo":F(), "ls":F(), "mkdir":F(), "pwd":F(), "rm":F(), "sh":F() }),
    "boot": D({ "grub": D({ "grub.cfg":F("set default=0\nset timeout=5") }), "vmlinuz-6.8.0":F(), "initrd.img":F() }),
    "dev":  D({ "null":F(), "zero":F(), "sda":F(), "tty":F() }),
    "etc":  D({
      "hostname":F("ubuntubox\n"),
      "os-release":F('NAME="Ubuntu"\nVERSION="24.04 LTS (Noble Numbat)"\nID=ubuntu\n'),
      "passwd":F("root:x:0:0:root:/root:/bin/bash\nuser:x:1000:1000:user:/home/user:/bin/bash\n"),
      "fstab":F("/dev/sda1  /  ext4  errors=remount-ro  0  1\n"),
      "hosts":F("127.0.0.1 localhost\n"),
      "ssh": D({ "sshd_config":F("Port 22\nPermitRootLogin no\n") }),
      "apt": D({ "sources.list":F("deb http://archive.ubuntu.com/ubuntu noble main\n") })
    }),
    "home": D({
      "user": D({
        "Documents": D({
          "welcome.txt":F("Welcome to your new desktop!\n"),
          "todo.md":F("- [ ] Water the plants\n- [x] Build a web desktop\n"),
          "notes.txt":F("Meeting notes go here.\n"),
          "resume.odt":F()
        }),
        "Downloads": D({
          "ubuntu-24.04-desktop-amd64.iso":F(),
          "wallpaper.png":F(),
          "archive.tar.gz":F()
        }),
        "Pictures": D({
          "screenshot-2024-05-01.png":F(),
          "cat.jpg":F(),
          "vacation": D({ "beach.jpg":F(), "mountains.jpg":F() })
        }),
        "Music":    D({ "favorite-song.flac":F() }),
        "Videos":   D({ "screencast.mp4":F() }),
        "Projects": D({ "hello.c":F('#include <stdio.h>\nint main(void){puts("hi");}\n'), "app.py":F("print('hello')\n") }),
        ".bashrc":F("alias ll='ls -alF'\nexport PS1='\\u@\\h:\\w\\$ '\n"),
        ".profile":F("# ~/.profile\n"),
        "notes.txt":F("Remember to buy milk.\n")
      })
    }),
    "lib":  D({ "modules":D({}), "x86_64-linux-gnu":D({}) }),
    "media":D({}),
    "mnt":  D({}),
    "opt":  D({}),
    "proc": D({ "cpuinfo":F("model name : Web CPU\n"), "meminfo":F("MemTotal: 16384000 kB\n"), "uptime":F("12345.67 40000.00\n") }),
    "root": D({}),
    "sbin": D({ "init":F(), "fsck":F(), "reboot":F() }),
    "srv":  D({}),
    "sys":  D({}),
    "tmp":  D({ ".X11-unix":D({}) }),
    "usr":  D({
      "bin":  D({ "python3":F(), "gcc":F(), "git":F(), "vim":F(), "curl":F() }),
      "lib":  D({ "python3.12":D({}), "gcc":D({}) }),
      "share":D({ "doc":D({ "README":F() }), "icons":D({}), "fonts":D({}) }),
      "local":D({ "bin":D({}), "lib":D({}) })
    }),
    "var":  D({
      "log":  D({ "syslog":F("May  1 10:00:01 ubuntubox CRON[812]: (root) CMD\n"), "auth.log":F(), "dmesg":F() }),
      "cache":D({ "apt":D({}) }),
      "tmp":  D({}),
      "spool":D({ "mail":D({}) })
    })
  });

  /* ================= Element handles ================= */
  const desktop    = document.getElementById("desktop");
  const filesWin   = document.getElementById("files-window");
  const notepadWin = document.getElementById("notepad-window");
  const filesList  = document.getElementById("files-list");
  const filesPath  = document.getElementById("files-path");
  const filesUp    = document.getElementById("files-up");
  const filesStatus= document.getElementById("files-status");
  const tabsEl     = document.getElementById("tabs");
  const newTabBtn  = document.getElementById("new-tab");
  const editor     = document.getElementById("editor");
  const clockEl    = document.getElementById("clock");

  /* ================= Files app ================= */
  let cwd = []; // path segments, [] == "/"

  function nodeAt(path){
    let node = FS;
    for (const seg of path) node = node.children[seg];
    return node;
  }
  function pathString(){ return "/" + cwd.join("/"); }

  function renderFiles(){
    filesPath.textContent = pathString();
    filesUp.disabled = (cwd.length === 0);
    filesList.innerHTML = "";

    const dir = nodeAt(cwd);
    const names = Object.keys(dir.children).sort(function(a,b){
      const A = dir.children[a], B = dir.children[b];
      if (A.type !== B.type) return A.type === "dir" ? -1 : 1;
      return a.localeCompare(b);
    });

    names.forEach(function(name){
      const entry = dir.children[name];
      const el = document.createElement("div");
      el.className = "fs-item";
      el.dataset.type = entry.type;
      el.textContent = name;
      el.title = name;

      el.addEventListener("click", function(){
        filesList.querySelectorAll(".fs-item.sel").forEach(function(i){ i.classList.remove("sel"); });
        el.classList.add("sel");
        filesStatus.textContent = '"' + name + '" selected (' + entry.type + ")";
      });

      el.addEventListener("dblclick", function(){
        if (entry.type === "dir"){
          cwd.push(name);
          renderFiles();
        } else {
          filesStatus.textContent = '"' + name + '" is a file — double-click folders to open them.';
        }
      });

      filesList.appendChild(el);
    });

    filesStatus.textContent = names.length + (names.length === 1 ? " item" : " items");
  }

  filesUp.addEventListener("click", function(){
    if (cwd.length > 0){ cwd.pop(); renderFiles(); }
  });

  renderFiles(); // initial listing of "/"

  /* ================= Notepad app (tabbed + persisted) ================= */
  const LS_KEY = "webdesktop.notepad.v1";
  let store = null;
  try { store = JSON.parse(localStorage.getItem(LS_KEY)); } catch(e){ store = null; }
  if (!store || !Array.isArray(store.tabs) || store.tabs.length === 0){
    store = { counter: 1, activeId: 1, tabs: [{ id: 1, name: "Untitled 1", content: "" }] };
  }
  if (typeof store.counter !== "number"){
    store.counter = store.tabs.reduce(function(m,t){ return Math.max(m, t.id||0); }, 0);
  }
  if (!store.tabs.some(function(t){ return t.id === store.activeId; })){
    store.activeId = store.tabs[0].id;
  }

  function saveStore(){
    try { localStorage.setItem(LS_KEY, JSON.stringify(store)); } catch(e){}
  }
  function activeTab(){
    return store.tabs.find(function(t){ return t.id === store.activeId; }) || store.tabs[0];
  }

  function renderTabs(){
    tabsEl.innerHTML = "";
    store.tabs.forEach(function(t){
      const el = document.createElement("div");
      el.className = "tab" + (t.id === store.activeId ? " active" : "");

      const label = document.createElement("span");
      label.className = "tab-name";
      label.textContent = t.name;

      const x = document.createElement("button");
      x.className = "tab-x";
      x.textContent = "×";
      x.title = "Close tab";
      x.addEventListener("click", function(e){
        e.stopPropagation();
        closeTab(t.id);
      });

      el.appendChild(label);
      el.appendChild(x);
      el.addEventListener("click", function(){ switchTab(t.id); });
      tabsEl.appendChild(el);
    });
  }

  function switchTab(id){
    if (store.activeId === id) return;
    const cur = activeTab();
    if (cur) cur.content = editor.value;
    store.activeId = id;
    saveStore();
    renderTabs();
    editor.value = activeTab().content;
  }

  function newTab(){
    const cur = activeTab();
    if (cur) cur.content = editor.value;
    store.counter += 1;
    const t = { id: store.counter, name: "Untitled " + store.counter, content: "" };
    store.tabs.push(t);
    store.activeId = t.id;
    saveStore();
    renderTabs();
    editor.value = "";
    editor.focus();
  }

  function closeTab(id){
    const idx = store.tabs.findIndex(function(t){ return t.id === id; });
    if (idx < 0) return;
    store.tabs.splice(idx, 1);
    if (store.tabs.length === 0){
      store.counter += 1;
      store.tabs.push({ id: store.counter, name: "Untitled " + store.counter, content: "" });
    }
    if (store.activeId === id){
      store.activeId = store.tabs[Math.min(idx, store.tabs.length - 1)].id;
    }
    saveStore();
    renderTabs();
    editor.value = activeTab().content;
  }

  editor.addEventListener("input", function(){
    activeTab().content = editor.value;
    saveStore();
  });
  newTabBtn.addEventListener("click", newTab);

  renderTabs();
  editor.value = activeTab().content;

  /* ================= Window manager ================= */
  let zTop = 10;

  function showWindow(win){
    win.style.display = "flex";
    win.style.zIndex = ++zTop;
  }

  document.getElementById("open-files").addEventListener("click", function(){
    showWindow(filesWin);
    renderFiles();
  });
  document.getElementById("open-notepad").addEventListener("click", function(){
    showWindow(notepadWin);
    editor.focus();
  });

  document.querySelectorAll(".window").forEach(function(win){
    win.addEventListener("pointerdown", function(){ win.style.zIndex = ++zTop; });

    win.querySelector(".win-close").addEventListener("click", function(){
      win.style.display = "none";
    });

    const bar = win.querySelector(".win-titlebar");
    bar.addEventListener("pointerdown", function(e){
      if (e.target.closest(".win-close")) return;
      e.preventDefault();
      win.style.zIndex = ++zTop;
      const rect = win.getBoundingClientRect();
      const offX = e.clientX - rect.left;
      const offY = e.clientY - rect.top;

      function onMove(ev){
        const d = desktop.getBoundingClientRect();
        let x = ev.clientX - d.left - offX;
        let y = ev.clientY - d.top - offY;
        y = Math.max(34, y);                       // stay below taskbar
        x = Math.max(-rect.width + 80, Math.min(x, d.width - 80));
        win.style.left = x + "px";
        win.style.top  = y + "px";
      }
      function onUp(){
        document.removeEventListener("pointermove", onMove);
        document.removeEventListener("pointerup", onUp);
      }
      document.addEventListener("pointermove", onMove);
      document.addEventListener("pointerup", onUp);
    });
  });

  /* ================= Clock ================= */
  function tick(){
    clockEl.textContent = new Date().toLocaleString(undefined, {
      weekday:"short", month:"short", day:"numeric",
      hour:"2-digit", minute:"2-digit"
    });
  }
  tick();
  setInterval(tick, 1000);

})();
</script>
</body>
</html>
